using System;

namespace Faolan.Core.Network.Packets
{
	// Builds the NewLevelIIR_t (sub-opcode 0x6D314743) body - the LEVEL-UP EVENT the client processes to draw the
	// "Congratulations, you have reached level N!" center-screen banner and play the level-up visual/audio effect.
	// The banner TEXT is client-side: it appears in NO capture (grep `Congratulations`/`reached level` on the
	// combat-levelup trace = 0 hits), so it is generated by the client's own level-up handler, gated on THIS packet.
	// Sending only the Level stat + the AttributeChanged feedback lines (as the pre-#209 path did) does not fire it.
	//
	// Carried as an IIR on the WORLD conversation (opcode 0x2000; sender = WorldFraming.Sender, receiver = the
	// player's GameInterface). Wire grammar (big-endian), decoded 2026-07-02 from the combat-levelup capture
	// (Blablabla_soldier-guardian..., frame 9937 - the L1->L2 ding), golden-tested in NewLevelIirCodecTests:
	//   [u32 len]          byte length of everything after this field
	//   [u32 0x6D314743]   NewLevelIIR_t sub-opcode
	//   [u32 0x0000C350]   Character marker (EntityClass.Character - same as every world IIR)
	//   [u32 instance]     the target GameInterface object (= the receiver endpoint instance / ClientInstance)
	//   [u8  0x00]         lead/env flag (constant 0 in the capture)
	//   [u32 newLevel]     the level just reached (2 in the capture -> "reached level 2")
	//   [u32 x6]           stat/derived deltas for the client's level-up summary panel (capture: 168,100,340,1,8,0).
	//                      Their exact per-class semantics are not yet decoded; the banner + effect key only off
	//                      newLevel, and the visible attribute gains ride the separate AttributeChanged lines, so the
	//                      live path sends zeros here (a display summary refinement is a follow-up).
	public static class NewLevelIirCodec
	{
		public const int DeltaCount = 6;
		public const uint SubOpcode = 0x6D314743;
		private const byte LeadFlag = 0x00;
		private const uint IirMarker = EntityClass.Character;

		// Full-control build (the golden test reproduces the captured deltas). `deltas` is padded/truncated to 6.
		public static byte[] Build(uint instance, uint newLevel, ReadOnlySpan<uint> deltas)
		{
			var content = new FaolanStream();
			content.WriteUInt32(SubOpcode).WriteUInt32(IirMarker).WriteUInt32(instance).WriteByte(LeadFlag).WriteUInt32(newLevel);
			for (var i = 0; i < DeltaCount; i++)
				content.WriteUInt32(i < deltas.Length
					? deltas[i]
					: 0u);

			var body = content.ToArray();
			var s = new FaolanStream();
			s.WriteUInt32(body.Length);
			s.WriteArray(body);
			return s.ToArray();
		}

		// Live path: the new level with an empty (all-zero) delta summary - enough to fire the banner + effect.
		public static byte[] Build(uint instance, uint newLevel)
		{
			return Build(instance, newLevel, ReadOnlySpan<uint>.Empty);
		}
	}
}
